-- Quiz AFROBACK : mythes, version 2 (récits réécrits le 2026-10-15)
-- Source : Mythologie/Cameroun/{Région}/{slug}/fr.md et en.md (textes identiques à supabase/mythes-v2_2026-10-15.sql). Rédigé par l'agent afroback-quiz.
-- BROUILLON : à relire par Yannick (FR) et par un anglophone (EN) avant exécution.
-- Remplace UNIQUEMENT les questions des 5 mythes. Questions des héros et tentatives non touchées.
-- bonne_reponse = index à partir de 0 dans choix_fr (même index dans choix_en).

begin;

delete from public.quiz_questions
where type_contenu = 'mythe'
  and slug in ('mythe-miengu-esprits-eau-sawa', 'mythe-nchare-yen-bamoun', 'mythe-ngan-medza-beti', 'mythe-ngog-lituba-bassa', 'mythe-sao-geants-kotoko');


commit;

-- Contrôle : chaque mythe doit avoir exactement 5 questions.
select slug, count(*) as nb_questions
from public.quiz_questions
where type_contenu = 'mythe'
  and slug in ('mythe-miengu-esprits-eau-sawa', 'mythe-nchare-yen-bamoun', 'mythe-ngan-medza-beti', 'mythe-ngog-lituba-bassa', 'mythe-sao-geants-kotoko')
group by slug
order by slug;
